-- Armored white horse: persisted equipment and authoritative travel restrictions.
insert into eldervale_private.realm_catalog(id,data) values ('item:mount:armoredWhiteHorse','{"name":"Armored white horse","field":"mountsOwned","key":"armoredWhiteHorse","slot":"mount","buy":2500,"sell":750,"unique":true,"multiplier":3}'::jsonb) on conflict(id) do update set data=excluded.data;

create or replace function eldervale_private.mount_allowed(px float8,pz float8) returns boolean language sql stable set search_path='' as $$
 select not(abs(px+340)<=51 and abs(pz+305)<=51) and not exists(
 select 1 from eldervale_private.entities e cross join lateral (select e.data as d) v
 where not e.deleted and d->>'template' in ('cottage','bank','inn','forge')
 and abs(px-(d->>'x')::float8)<30 and abs(pz-(d->>'z')::float8)<30
 and abs((px-(d->>'x')::float8)*cos(coalesce((d->>'yaw')::float8,0)*pi()/180)-(pz-(d->>'z')::float8)*sin(coalesce((d->>'yaw')::float8,0)*pi()/180))<=2.3*1.3*coalesce((d->>'scale')::float8,1)
 and abs((px-(d->>'x')::float8)*sin(coalesce((d->>'yaw')::float8,0)*pi()/180)+(pz-(d->>'z')::float8)*cos(coalesce((d->>'yaw')::float8,0)*pi()/180))<=2.15*1.3*coalesce((d->>'scale')::float8,1))
$$;
create or replace function eldervale_private.mounted(uid uuid,px float8,pz float8) returns boolean language sql stable set search_path='' as $$
 select coalesce((select s.equipment->>'mount'='armoredWhiteHorse' and coalesce(s.inventory->'mountsOwned','[]')?'armoredWhiteHorse' and s.health>0 from public.player_saves s where s.user_id=uid),false)
 and eldervale_private.mount_allowed(px,pz)
 and not exists(select 1 from eldervale_private.realm_actors where target=uid and not deleted and hp>0)
 and not exists(select 1 from eldervale_private.gathering_actions where user_id=uid)
$$;
revoke all on function eldervale_private.mount_allowed(float8,float8),eldervale_private.mounted(uuid,float8,float8) from public,anon,authenticated;


